INSERT INTO "frikiparty_game_map" ("game_id", "name", "players")
SELECT g."id", b."name", 8 FROM "booklet_board" b CROSS JOIN "frikiparty_game" g WHERE g."name" = 'Age of the Ring'
ON CONFLICT ("game_id", "name") DO NOTHING;--> statement-breakpoint
